stepxmp.pre:
@media print and (width >= 6in) {
    chapter { color: black; }
}

@media screen, (overflow-block: paged) {
    title { break-before: page; }
}

@supports (color: navy) and selector(chapter > title) {
    chapter > title { color: navy; }
}

@supports not (frobnicate: 1) {
    title { margin-left: 1em; }
}

@supports-condition --basic-layout {
    display: block;
    color: navy;
}

@supports (--basic-layout) {
    chapter { display: block; }
}

@when media(overflow-block: paged) and supports(color: navy) {
    title { color: navy; }
} @else supports(color: black) {
    title { color: black; }
} @else {
    title { color: inherit; }
}

chapter {
    container-name: page-box;
    --theme: dark;
}

@container page-box style(--theme: dark) {
    title { color: white; }
}
